import sys

def solution(out, br, n, mod):
    dp = [[0] * (n * n + 5) for _ in range(n)]
    dp[0][0] = 1
    for i in range(1, n):
        for j in range(len(dp[0])):
            for c in range(i + 1):
                if j - c >= 0:
                    dp[i][j] += dp[i - 1][j - c]
                    dp[i][j] %= mod
                    if dp[i][j] == 0:
                        dp[i][j] += mod

    sums = [[0] * len(dp[0]) for _ in range(n)]
    for i in range(n):
        sumAcc = 0
        for j in range(len(dp[0])):
            sumAcc += dp[i][j]
            sumAcc %= mod
            if sumAcc == 0:
                sumAcc += mod
            sums[i][j] = sumAcc

    fact = [1] * (501 * 501)
    for i in range(1, len(fact)):
        fact[i] = (fact[i - 1] * i) % mod

    nCr = [[0] * 501 for _ in range(501)]
    nCr[0][0] = 1
    for i in range(1, 501):
        nCr[i][0] = 1
        for j in range(1, 501):
            nCr[i][j] = (nCr[i - 1][j] + nCr[i - 1][j - 1]) ) % mod
            if nCr[i][j] == 0:
                nCr[i][j] += mod

    res = 0
    for i in range(n - 2, -1, -1):
        cnt = n - i
        pre = n - cnt
        comb = (nCr[n][pre] * fact[pre]) % mod
        if comb == 0:
            comb += mod
        totalSum = 0
        for dif in range(1, cnt):
            for inv in range(dif, len(dp[0])):
                if dp[cnt - 2][inv] == 0:
                    break
                if inv - dif - 1 < 0:
                    continue
                val = dp[cnt - 2][inv]
                ySum = sums[cnt - 2][inv - dif - 1]
                val = (val * ySum) % mod
                if val == 0:
                    val += mod
                totalSum += val * (cnt - dif)
                totalSum %= mod
        res += totalSum * comb
        res %= mod
        if res == 0:
            res += mod
    out.write(str(res % mod) + "\n")

def main():
    input_lines = sys.stdin.read().splitlines()
    inputLine = input_lines[0]
    T = 1
    # Since the original code reads only one line, we process that
    n, mod = map(int, inputLine.split())
    solution(sys.stdout, sys.stdin, n, mod)

if __name__ == "__main__":
    main()

